<script setup lang="ts">
import { ref } from 'vue'
import type { PerformanceLevel } from '@englishflow/performance'
export type MobileQuestion = { id: string; type: 'CHOICE' | 'FILL_BLANK' | 'DRAG_SORTER' | 'LISTEN' | 'TRANSLATION'; prompt: string; sentence?: string; sourceText?: string; audioUrl?: string | null; options?: Array<{ key: string; text: string }>; tokens?: Array<{ tokenId: string; text: string }> }
defineProps<{ question: MobileQuestion; disabled?: boolean; performanceLevel: PerformanceLevel }>()
const emit = defineEmits<{ answer: [value: unknown] }>()
const selected = ref<string | null>(null); const translation = ref(''); const ordered = ref<string[]>([]); const playing = ref(false)
function choose(value: string): void { selected.value = value; emit('answer', value) }
function toggleToken(tokenId: string): void { ordered.value = ordered.value.includes(tokenId) ? ordered.value.filter((id) => id !== tokenId) : [...ordered.value, tokenId]; emit('answer', ordered.value) }
</script>
<template><view class="question-card"><text class="prompt">{{ question.prompt }}</text><text v-if="question.type === 'FILL_BLANK' && question.sentence" class="sentence">{{ question.sentence }}</text><text v-if="question.type === 'TRANSLATION' && question.sourceText" class="sentence">{{ question.sourceText }}</text><button v-if="question.type === 'LISTEN'" class="audio" type="button" :disabled="!question.audioUrl" @click="playing = !playing">{{ question.audioUrl ? (playing ? 'Ⅱ 播放中' : '▶ 播放音频') : '音频不可用' }}</button><text v-if="question.type === 'LISTEN' && !question.audioUrl" class="notice">服务端未返回音频资源，未伪造播放成功。</text><view v-if="question.type === 'DRAG_SORTER'" class="tokens"><button v-for="token in question.tokens ?? []" :key="token.tokenId" class="token" type="button" :disabled="disabled" :class="{ 'token--selected': ordered.includes(token.tokenId) }" @click="toggleToken(token.tokenId)">{{ token.text }}</button></view><view v-else-if="question.type === 'TRANSLATION'" class="translation"><textarea v-model="translation" :disabled="disabled" placeholder="输入你的译文" @blur="emit('answer', translation)" /><button class="submit" type="button" :disabled="disabled || !translation.trim()" @click="emit('answer', translation)">提交译文</button></view><view v-else class="options"><button v-for="option in question.options ?? []" :key="option.key" class="option" :class="{ 'option--selected': selected === option.key }" type="button" :disabled="disabled" @click="choose(option.key)">{{ option.key }} · {{ option.text }}</button></view></view></template>
<style scoped lang="scss">.question-card{display:grid;gap:22rpx;padding:24rpx;border:1rpx solid #e6e8f0;border-radius:20rpx;background:#fff}.prompt{font-size:34rpx;font-weight:750;line-height:1.45}.sentence{padding:18rpx;border-radius:14rpx;color:#596bff;background:#eef0ff;font-size:28rpx;line-height:1.6}.audio,.submit{min-height:88rpx;border:0;border-radius:16rpx;color:#fff;background:#596bff;font-size:28rpx;font-weight:700}.audio:disabled{color:#666d80;background:#f3f4f8}.notice{padding:16rpx;border-radius:12rpx;color:#9b5b00;background:#fff7e8;font-size:22rpx}.options,.tokens{display:grid;gap:12rpx}.option,.token{min-height:88rpx;padding:0 18rpx;border:1rpx solid #e6e8f0;border-radius:14rpx;color:#202332;background:#fff;text-align:left;font-size:25rpx}.option--selected,.token--selected{border-color:#596bff;color:#596bff;background:#eef0ff}.translation{display:grid;gap:12rpx}textarea{width:100%;padding:18rpx;border:1rpx solid #d9dce7;border-radius:14rpx;box-sizing:border-box;font-size:26rpx;line-height:1.6}</style>
